const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const n = Number(input[0]);
const first = input[1];
const m = Number(input[2]);
const second = input[3];

let common = 0;
const limit = Math.min(n, m);

while (common < limit && first[common] === second[common]) {
  common++;
}

